import { buildHeaders, buildXHeaders } from './utils';
import { AuthenticationError, ResponseError } from '../exceptions';
import { Tokens, WithXHeaders } from '../interfaces';

interface GetTokensCountArgs {
  input: string[];
  model: string;
  accessToken?: string;
}

function getRequestConfig({ input, model, accessToken }: GetTokensCountArgs): AxiosRequestConfig {
  const headers = buildHeaders(accessToken);

  const data = { model, input };

  return {
    method: 'POST',
    url: '/tokens/count',
    headers: headers,
    data: data,
  } as AxiosRequestConfig;
}

function buildResponse(response: AxiosResponse): Tokens & WithXHeaders {
  if (response.status === 200) {
    return buildXHeaders(response, { tokens: response.data } as Tokens);
  } else if (response.status === 401) {
    throw new AuthenticationError(response);
  } else {
    throw new ResponseError(response);
  }
}

export async function post_tokens_count(
  client: AxiosInstance,
  args: GetTokensCountArgs,
): Promise<Tokens & WithXHeaders> {
  const config = getRequestConfig(args);
  const response = await client.request(config);
  return buildResponse(response);
}

import { USER_AGENT } from '../constants';
import { AxiosResponse } from 'axios';
import { WithXHeaders } from 'gigachat/interfaces';

export function buildHeaders(accessToken?: string): Record<string, string> {
  const headers: Record<string, string> = {};

  if (accessToken) {
    headers['Authorization'] = `Bearer ${accessToken}`;
  }
  if (!isRunningInBrowser()) {
    headers['User-Agent'] = USER_AGENT;
  } else {
    headers['X-User-Agent'] = USER_AGENT;
  }

  return headers;
}

export function parseChunk<T>(line: string): T | null {
  try {
    const idx = line.indexOf(': ');
    if (idx === -1) return null;
    const name = line.substring(0, idx);
    const value = line.substring(idx + 2);
    if (name === 'data') {
      if (value === '[DONE]') {
        return null;
      } else {
        return value ? JSON.parse(value) : null;
      }
    }
  } catch (e) {
    console.error(`Error parsing chunk from server: ${e}, raw value: ${line}`);
    throw e;
  }
  return null;
}

export function buildXHeaders<T>(response: AxiosResponse, data: T): T & WithXHeaders {
  const headers = response.headers;
  const withXHeaders: WithXHeaders = {
    xHeaders: {},
  };
  if (headers) {
    withXHeaders.xHeaders = {
      xRequestID: headers['x-request-id'],
      xSessionID: headers['x-session-id'],
      xClientID: headers['x-client-id'],
    };
  }
  return {
    ...data,
    ...withXHeaders,
  };
}

export function isRunningInBrowser() {
  return (
    // @ts-ignore
    typeof window !== 'undefined' &&
    // @ts-ignore
    typeof window.document !== 'undefined' &&
    // @ts-ignore
    typeof navigator !== 'undefined'
  );
}

export { USER_AGENT };
